import json
from pathlib import Path

import numpy as np
import jax
import jax.numpy as jnp


def task_basic_reduce(input_path: str) -> np.ndarray:
    x = jnp.asarray(np.load(input_path))
    return np.asarray(jnp.mean(x, axis=1))


def task_map_square(input_path: str) -> np.ndarray:
    x = jnp.asarray(np.load(input_path))
    return np.asarray(jnp.square(x))


def task_grad_logistic(input_path: str) -> np.ndarray:
    data = np.load(input_path)
    x = jnp.asarray(data["x"])
    y = jnp.asarray(data["y"])
    w = jnp.asarray(data["w"])

    def loss_fn(w_vec: jnp.ndarray) -> jnp.ndarray:
        z = jnp.dot(x, w_vec)
        return jnp.mean(jnp.logaddexp(0.0, -y * z))

    grad = jax.grad(loss_fn)(w)
    return np.asarray(grad)


def task_scan_rnn(input_path: str) -> np.ndarray:
    data = np.load(input_path)
    seq = jnp.asarray(data["seq"])
    init = jnp.asarray(data["init"])
    wx = jnp.asarray(data["Wx"])
    wh = jnp.asarray(data["Wh"])
    b = jnp.asarray(data["b"])

    def step(h, x_t):
        h_next = jnp.tanh(wx @ x_t + wh @ h + b)
        return h_next, h_next

    _, hs = jax.lax.scan(step, init, seq)
    return np.asarray(hs)


def task_jit_mlp(input_path: str) -> np.ndarray:
    data = np.load(input_path)
    x = jnp.asarray(data["X"])
    w1 = jnp.asarray(data["W1"])
    b1 = jnp.asarray(data["b1"])
    w2 = jnp.asarray(data["W2"])
    b2 = jnp.asarray(data["b2"])

    @jax.jit
    def forward(x_in):
        h = jnp.maximum(0.0, x_in @ w1 + b1)
        return h @ w2 + b2

    return np.asarray(forward(x))


TASKS = {
    "basic_reduce": task_basic_reduce,
    "map_square": task_map_square,
    "grad_logistic": task_grad_logistic,
    "scan_rnn": task_scan_rnn,
    "jit_mlp": task_jit_mlp,
}


def main() -> None:
    with open("problem.json", "r", encoding="utf-8") as f:
        problems = json.load(f)

    for problem in problems:
        task_id = problem["id"]
        input_path = problem["input"]
        output_path = Path(problem["output"])

        if task_id not in TASKS:
            raise ValueError(f"Unknown task id: {task_id}")

        result = TASKS[task_id](input_path)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        np.save(output_path, result)


if __name__ == "__main__":
    main()
